"""Self-contained HTML from measured simulation results; no fetch or CDN."""
import html,json

def render(report):
 e=lambda s:html.escape(str(s))
 rows=''.join('<tr><td><button onclick="show('+str(i)+')">'+e(x['id'])+'</button><br>'+e(x['description'])+'</td><td>'+('PASS' if x['passed'] else 'FAIL')+'</td><td>'+e(x['actual']['outcome'])+'</td><td>'+str(x['actual']['attempts'])+'</td><td>'+str(x['actual']['series_saves'])+'</td><td>'+e(x['actual']['closeout_verified'])+'</td><td><a href="'+e(x['result'])+'">Result</a> · <a href="'+e(x['log'])+'">Log</a></td></tr>' for i,x in enumerate(report['scenarios']))
 return '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Invoice core simulation results</title><style>body{font:16px/1.6 system-ui;max-width:1160px;margin:30px auto;padding:0 20px;color:#203044;background:#fafbfd}h1{font-size:30px}.notice{padding:16px;background:#fff3d6;border-left:4px solid #b77916}table{border-collapse:collapse;width:100%;background:white}th,td{border:1px solid #dce2e8;padding:10px;text-align:left;vertical-align:top}th{background:#edf2f7}button{font:inherit;color:#075caa;background:none;border:0;padding:0;text-decoration:underline;cursor:pointer}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:white;border:1px solid #dce2e8;padding:20px}.scroll{overflow:auto}a{color:#075caa}</style><h1>Invoice core · simulation results</h1><p class="notice"><strong>Synthetic data · adapted real core · No model calls · no live services.</strong><br>PASS means every predeclared field matched. A correctly blocked negative case is a test pass, never an invoice success.</p><p>'''+str(sum(x['passed'] for x in report['scenarios']))+' / '+str(len(report['scenarios']))+''' required scenarios passed. <a href="evaluation-results.json">Evaluation JSON</a> · <a href="run-log.jsonl">Structured logs</a></p><div class="scroll"><table><thead><tr><th>Scenario</th><th>Test</th><th>Workflow outcome</th><th>Issue attempts</th><th>Series saves</th><th>Closeout verified</th><th>Evidence</th></tr></thead><tbody>'''+rows+'''</tbody></table></div><h2>Inspect a scenario</h2><p>Select a scenario above to compare expectations with measured output.</p><pre id="detail"></pre><h2>Boundaries</h2><p>The original project used external AI agents for tool orchestration and exception handling. This demo exercises selected Python state and tracker rules with deterministic simulated tools. Fixture operator labels do not prove a real user's identity or consent. No tax or invoice validity is established.</p><script>const rows='''+json.dumps(report['scenarios']).replace('<','\\u003c')+''';function show(i){document.getElementById('detail').textContent=JSON.stringify(rows[i],null,2)}show(0)</script></html>'''
